using System.Text.Json;
namespace Arcoll.WinUI3.Services.BackupCenter;
public sealed class BackupRepository
{
 public string Root{get;}
 public BackupRepository(BackupPlan plan){BackupSafety.DataRoot(plan.Settings.Destination);foreach(var source in plan.Settings.Folders){var expanded=Environment.ExpandEnvironmentVariables(source);if(BackupSafety.Inside(plan.Settings.Destination,expanded)||BackupSafety.Inside(expanded,plan.Settings.Destination))throw new IOException("Origem e destino local não podem conter um ao outro.");}var store=plan.StoreKey.Length==64?plan.StoreKey:BackupSafety.HashText(JsonSerializer.Serialize(new object?[]{plan.Target,plan.ConnectionId,plan.Settings.Destination.ToLowerInvariant()},new JsonSerializerOptions{Encoder=System.Text.Encodings.Web.JavaScriptEncoder.UnsafeRelaxedJsonEscaping}));
  Root=BackupSafety.SafeChild(plan.Settings.Destination,"TIDigitalBackup",plan.NetworkId+"-"+plan.AgentId,plan.Id,store);var marker=BackupSafety.SafeChild(Root,"repository.json");var expected=JsonSerializer.Serialize(new{schema="tidigital.backup.repo.v1",plan=plan.Id,network=plan.NetworkId,agent=plan.AgentId,store});
  if(Directory.Exists(Root)){if(!File.Exists(marker)||File.ReadAllText(marker)!=expected)throw new IOException("Destino já contém uma pasta sem identidade válida deste repositório.");}else{Directory.CreateDirectory(Root);BackupSafety.Atomic(marker,expected);}Directory.CreateDirectory(BackupSafety.SafeChild(Root,"objects"));Directory.CreateDirectory(BackupSafety.SafeChild(Root,"points"));
 }
 public string ObjectPath(string digest){if(!System.Text.RegularExpressions.Regex.IsMatch(digest,"^[a-f0-9]{64}$"))throw new IOException("Hash de objeto inválido.");return BackupSafety.SafeChild(Root,"objects",digest[..2],digest);}
 public async Task<bool> PutAsync(string spool,string digest,Func<long,Task> progress,CancellationToken ct){var final=ObjectPath(digest);if(File.Exists(final)){if(await BackupSafety.HashFileAsync(final,async _=>await progress(0),ct)!=digest)throw new IOException("Objeto local existente está corrompido; corrija o repositório antes de reutilizar.");return false;}Directory.CreateDirectory(Path.GetDirectoryName(final)!);var temp=final+"."+Guid.NewGuid().ToString("N")+".partial";
  try{await using(var source=new FileStream(spool,FileMode.Open,FileAccess.Read,FileShare.Read,1048576,true))await using(var target=new FileStream(temp,FileMode.CreateNew,FileAccess.Write,FileShare.None,1048576,true)){var buffer=new byte[1048576];int size;while((size=await source.ReadAsync(buffer,ct))>0){await target.WriteAsync(buffer.AsMemory(0,size),ct);await progress(size);}await target.FlushAsync(ct);target.Flush(true);}if(await BackupSafety.HashFileAsync(temp,async _=>await progress(0),ct)!=digest)throw new IOException("Checksum local não confere.");BackupSafety.NoLinks(final);File.Move(temp,final,false);return true;}finally{if(File.Exists(temp))File.Delete(temp);}}
 public void SavePoint(string id,string canonical,string digest){if(BackupSafety.HashText(canonical)!=digest)throw new IOException("Manifesto local não confere.");var name=BackupSafety.SafeChild(Root,"points",id+".json");BackupSafety.Atomic(name,canonical);BackupSafety.Atomic(name+".sha256",digest);}
 public Stream Open(BackupFile file){var path=ObjectPath(file.Digest);BackupSafety.NoLinks(path);return new FileStream(path,FileMode.Open,FileAccess.Read,FileShare.Read,1048576,true);}
}
